  "Bake until the top is slightly browned and the center is set and doesn't wobble. Whole egg with runny yolk: start checking at 12 to 14 min.": "तब तक बेक करें जब तक ऊपर से हल्का भूरा न हो जाए और बीच जम जाए और हिले नहीं। कच्ची ज़र्दी वाला साबुत अंडा: 12 से 14 मिनट पर जाँचना शुरू करें।",
  "Center set, no wobble": "बीच जमा, हिलता नहीं",
  "Rest in the pan": "ट्रे में आराम",
