  "Wash the leaves": "पत्ते धोना",
  "Separate the lettuce into leaves and wash them thoroughly in a colander.": "लेट्यूस के पत्ते अलग करें और छलनी में अच्छी तरह धोएँ।",
  "Let the leaves dry": "पत्ते सूखने देना",
  "Let them dry completely: no wet leaves. A salad spinner or towel speeds it up.": "उन्हें पूरी तरह सूखने दें: कोई गीला पत्ता नहीं। सलाद स्पिनर या टॉवल से जल्दी होता है।",
  "No water left": "पानी नहीं बचा",
  "Carrot ribbons": "गाजर की पट्टियाँ",
