  "Cucumber ribbons": "खीरे की पट्टियाँ",
  "Peel ribbons from all sides of the unpeeled cucumber, skin included. Stop at the seedy core.": "बिना छिले खीरे की हर तरफ़ से छिलके समेत पट्टियाँ छीलें। बीज वाले बीच पर रुक जाएँ।",
  "Ribbons, core left over": "पट्टियाँ, बीच बचा",
  "Tear the herbs": "हर्ब्स तोड़ना",
  "Tear the basil and mint by hand (don't cut them).": "तुलसी (बेसिल) और पुदीना हाथ से तोड़ें (काटें नहीं)।",
  "Torn": "तोड़े हुए",
  "Shake the dressing": "ड्रेसिंग हिलाना",
