  "Even sauce": "एकसार सॉस",
  "Spread and top": "फैलाना और टॉपिंग",
  "Spread the pizza sauce (or sour cream) on each tortilla, leaving about 1 cm at the edge. Add the toppings: ham and cheese (or bacon, garlic, red onion and cheese).": "हर टॉर्टिया पर पिज़्ज़ा सॉस (या खट्टी क्रीम) फैलाएँ, किनारे पर लगभग 1 सेमी छोड़ दें। टॉपिंग डालें: हैम और चीज़ (या बेकन, लहसुन, लाल प्याज़ और चीज़)।",
  "All tortillas topped": "सभी टॉर्टिया पर टॉपिंग",
  "Bake in the oven": "ओवन में बेक करना",
  "Bake on the hot tray.": "गरम ट्रे पर बेक करें।",
  "Tortilla edge browned": "टॉर्टिया का किनारा भूरा",
  "Slice and serve": "काटना और परोसना",
  "Take them out and slice each tozza into 4.": "निकालें और हर एक को 4 टुकड़ों में काटें।",
  "Preheat the oven … Bake in the oven": "ओवन पहले से गरम करना … ओवन में बेक करना",
  "Panini press": "पानिनी प्रेस",
  "Set the press so it leaves a gap and the top surface almost touches the toppings. Cook.": "प्रेस ऐसे सेट करें कि थोड़ी जगह रहे और ऊपरी सतह लगभग टॉपिंग को छुए। पकाएँ।",
  "Dice the toppings": "टॉपिंग काटना",
