  "Ladle into bowls and add grated cheese on top (and a splash of cream or a few basil leaves, if chosen).": "कटोरों में करछी से डालें और ऊपर कद्दूकस किया चीज़ डालें (और चुना हो तो थोड़ी क्रीम या तुलसी के कुछ पत्ते)।",
